function validate([head]) {
  if (!Array.isArray(head) || head.length > 300) return 'The list holds at most 300 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < -100 || v > 100)) return 'Each node value is an integer between -100 and 100.';
  for (let i = 1; i < head.length; i++) if (head[i] < head[i - 1]) return 'The list must be sorted in non-decreasing order.';
  return null;
}

