function deleteDuplicates(head) {
  const counts = new Map();
  const order = [];
  for (let p = head; p; p = p.next) {
    if (!counts.has(p.val)) order.push(p.val);
    counts.set(p.val, (counts.get(p.val) || 0) + 1);
  }
  const kept = order.filter(v => counts.get(v) === 1);
  let result = null;
  for (let k = kept.length - 1; k >= 0; k--) result = new ListNode(kept[k], result);
  return result;
}

