function generate(rand, size) {
  const n = size === 'large' ? 300 : Math.floor(rand() * 9);
  const span = size === 'large' ? 100 : (rand() < 0.5 ? 3 : 100);
  const list = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  list.sort((a, b) => a - b);
  return [list];
}
